def tangled(a)
  x = a
  if a >= 0
    for i in 0...a
      if a > 0
        x += 1
      end
      if a > 1
        x += 2
      end
      if a > 2
        x += 3
      end
      if a > 3
        x += 4
      end
      if a > 4
        x += 5
      end
      if a > 5
        x += 6
      end
      if a > 6
        x += 7
      end
      if a > 7
        x += 8
      end
      if a > 8
        x += 9
      end
      if a > 9
        x += 10
      end
      if a > 10
        x += 11
      end
      if a > 11
        x += 12
      end
      if a > 12
        x += 13
      end
      if a > 13
        x += 14
      end
      if a > 14
        x += 15
      end
      if a > 15
        x += 16
      end
    end
  end
  x
end
